UPDATE OFT_REVIEW
SET DELETED_AT = SYSTIMESTAMP,
    UPDATED_AT = SYSTIMESTAMP
WHERE REVIEW_NO = #{reviewNo}
  AND USER_NO = #{userNo}
  AND DELETED_AT IS NULL

UPDATE OFT_REVIEW
SET RATING = #{rating},
    CONTENT = #{content},
    UPDATED_AT = SYSTIMESTAMP
WHERE REVIEW_NO = #{reviewNo}
  AND USER_NO = #{userNo}
  AND RECIPE_NO = #{recipeNo}
  AND DELETED_AT IS NULL

UPDATE OFT_REVIEW
SET DELETED_AT = SYSTIMESTAMP,
    UPDATED_AT = SYSTIMESTAMP
WHERE REVIEW_NO = #{reviewNo}
  AND USER_NO = #{userNo}
  AND RECIPE_NO = #{recipeNo}
  AND DELETED_AT IS NULL
